using System;
using System.Collections.Generic;
namespace MassiveArmy.Industrial {
    [Serializable] public sealed class IndustrialWasteSite {public long sluice,pile;public FramePose pose;}
    public sealed partial class IndustrialWorld {
        static readonly string[] TailingsItems={"tailings","radioactive-tailings"};
        public const long FrontTailingsCapacity=5000,CleanupBatchThreshold=500;public const int CleanupIntervalTicks=200;
        long miningSiteRevision,builtMiningSiteRevision=-1;int builtMiningSiteCount=-1;
        readonly Dictionary<long,List<IndustrialMachine>> miningSites=new Dictionary<long,List<IndustrialMachine>>();
        public static long TailingsCount(Inventory inventory)=>inventory==null?0:inventory.Count("tailings")+inventory.Count("radioactive-tailings");
        public static double TailingsActivity(Inventory inventory){if(inventory==null)return 0;double sum=0;foreach(var item in inventory.items)sum+=item.activity;return sum;}
        public static long MoveTailings(Inventory from,Inventory to,long count){if(from==null||to==null||ReferenceEquals(from,to)||count<=0)return 0;long left=Math.Min(count,Math.Min(TailingsCount(from),to.Free));long total=left;foreach(string item in TailingsItems){long amount=Math.Min(left,from.Count(item));if(amount>0){if(Inventory.Transfer(from,to,item,amount))left-=amount;}}return total-left;}
        public static double TailingsRadius(long litres)=>litres<=0?0:Math.Pow(litres/1000d/(Math.PI*.7/3),1d/3);
        public static FramePose TailingsPose(IndustrialMachine sluice)=>IndustrialHaulNavigation.SurfaceOffset(sluice.pose,2.7,-4.5);
        public string FrontDischargeObstruction(FramePose point,double clearance){if(!miningWorkflow)return null;foreach(var m in machines){if(m.definition!="sluice"||m.pose.body!=point.body||m.pose.frame!=point.frame||!HaulNear(m.pose,point,10))continue;var outlet=TailingsPose(m);double radius=Math.Sqrt(outlet.x*outlet.x+outlet.y*outlet.y+outlet.z*outlet.z),dx=point.x-outlet.x,dy=point.y-outlet.y,dz=point.z-outlet.z,height=radius<1?dy:(dx*outlet.x+dy*outlet.y+dz*outlet.z)/radius;double flat=dx*dx+dy*dy+dz*dz-height*height;if(height>=-clearance&&height<=1.4+clearance&&flat<(2+clearance)*(2+clearance))return "Route crosses the reserved front tailings discharge area of sluice #"+m.id;}return null;}
        public bool IsTailingsSource(long id)=>Pile(id)?.tailingsPile==true||miningWorkflow&&Machine(id)?.definition=="sluice";
        public bool CanWaitForHaulSource(long id)=>Pile(id)!=null||IsTailingsSource(id);
        Inventory TailingsSourceInventory(long id){var pile=Pile(id);return pile?.tailingsPile==true?pile.tailings:Machine(id)?.frontTailings;}
        public static long HaulCargo(IndustrialMachine vehicle)=>vehicle.haul?.role=="tailings"?TailingsCount(vehicle.input):vehicle.input.bulk.litres;
        public void EnableMiningWorkflow(){if(miningWorkflow)return;miningWorkflow=true;foreach(var vehicle in machines)if(vehicle.haul?.active==true&&vehicle.haul.role==null){vehicle.haul.role=vehicle.definition=="excavator"?"excavate":vehicle.definition=="truck"?"transport":"haul";}miningSiteRevision++;foreach(var m in machines)if(m.definition=="sluice"){m.frontTailings??=new Inventory{capacity=FrontTailingsCapacity};MoveTailings(m.output,m.frontTailings,TailingsCount(m.output));}}
        void WashToFront(IndustrialMachine m){
            m.frontTailings??=new Inventory{capacity=FrontTailingsCapacity};MoveTailings(m.output,m.frontTailings,TailingsCount(m.output));
            if(m.input.bulk.litres<10){m.status="Needs pay dirt";return;}if(m.water<2){m.status="Needs water";return;}
            var remaining=m.input.bulk;var batch=remaining.Take(10);long ore=batch.iron+batch.copper+batch.radioactive,waste=Math.Max(0,batch.litres-ore);
            if(!m.output.CanFit(ore)){m.status="Ore output blocked";return;}if(!m.frontTailings.CanFit(waste)){m.status="Front tailings heap full · assign a cleanup digger";return;}
            long activeUnits=batch.radioactive+waste;double oreActivity=activeUnits>0?(double)batch.activity*batch.radioactive/activeUnits:batch.activity;
            m.input.bulk=remaining;m.water--;
            if(batch.iron>0)m.output.Add("iron-ore",batch.iron,activeUnits==0?oreActivity:0);if(batch.copper>0)m.output.Add("copper-ore",batch.copper,activeUnits==0&&batch.iron==0?oreActivity:0);if(batch.radioactive>0)m.output.Add("radioactive-ore",batch.radioactive,oreActivity);
            if(waste>0)m.frontTailings.Add(batch.activity>0?"radioactive-tailings":"tailings",waste,batch.activity-oreActivity);m.status="Washing · tailings discharged at front";
        }
        void ReadMiningSites(){if(builtMiningSiteRevision==miningSiteRevision&&builtMiningSiteCount==machines.Count)return;miningSites.Clear();foreach(var vehicle in machines)if(vehicle.haul?.active==true&&vehicle.haul.role=="excavate"){if(!miningSites.TryGetValue(vehicle.haul.source,out var site)){site=new List<IndustrialMachine>();miningSites.Add(vehicle.haul.source,site);}site.Add(vehicle);}builtMiningSiteRevision=miningSiteRevision;builtMiningSiteCount=machines.Count;}
        long SiteBucketStock(long source,long owner=0){if(!miningWorkflow)return 0;ReadMiningSites();long stock=0;if(miningSites.TryGetValue(source,out var site))foreach(var vehicle in site)if(vehicle.haul.active&&(owner==0||vehicle.owner==owner))stock+=vehicle.input.bulk.litres;return stock;}
        public List<long> ActiveMiningSites(long owner,FramePose origin){var result=new List<long>();ReadMiningSites();foreach(var pair in miningSites){foreach(var digger in pair.Value)if(digger.owner==owner&&digger.haul.active&&digger.enabled&&digger.integrity>0&&(creativeMode&&digger.haul.freeFuel||digger.progress>0||digger.input.Count("fuel")>0)&&HaulSource(owner,pair.Key,out var pose,out long stock)&&origin.Distance(pose)<double.PositiveInfinity&&stock>0){result.Add(pair.Key);break;}}result.Sort((a,b)=>{HaulSource(owner,a,out var pa,out _);HaulSource(owner,b,out var pb,out _);return origin.Distance(pa).CompareTo(origin.Distance(pb));});return result;}
        public bool MiningLoaderPose(long source,long owner,FramePose origin,out FramePose loading){ReadMiningSites();loading=default;double best=double.PositiveInfinity;if(!miningSites.TryGetValue(source,out var site))return false;foreach(var loader in site){if(loader.owner!=owner||!loader.haul.active||!loader.enabled||loader.integrity<=0||!(creativeMode&&loader.haul.freeFuel)&&loader.progress<=0&&loader.input.Count("fuel")==0)continue;var pose=loader.haul.phase==1?loader.pose:loader.haul.route[loader.haul.pickupIndex];double d=origin.Distance(pose);if(d<best){best=d;loading=pose;}}return best<double.PositiveInfinity;}
        public long RawSourceRemaining(long source)=>Pile(source)?.material.litres??Deposit(source)?.remaining.litres??0;
        bool UseJobFuel(IndustrialMachine vehicle,int energy){if(creativeMode&&vehicle.haul.freeFuel){if(vehicle.haul.role==null&&vehicle.progress>0)vehicle.progress--;return true;}if(vehicle.progress<energy){if(!vehicle.input.Remove("fuel",1)){vehicle.haul.status="Needs fuel in vehicle input";return false;}vehicle.progress+=100;}vehicle.progress-=energy;return true;}
        int DrivingEnergy(IndustrialMachine vehicle)=>vehicle.haul.role==null?1:vehicle.definition=="excavator"?4:vehicle.definition=="loader"?2:1;
        void StepExcavation(IndustrialMachine digger){
            var job=digger.haul;long stock=RawSourceRemaining(job.source);if(stock<=0){job.status=digger.input.bulk.litres>0?"Node depleted · waiting for truck to take last bucket":"Node depleted · select next worksite";return;}if(Pile(job.source)==null&&MiningBlocked(Deposit(job.source).pose)){job.status="Excavation would undermine construction";return;}
            long amount=Math.Min(50,Math.Min(stock,digger.input.Free));if(amount<=0){job.status="Bucket full · waiting for a dump truck";return;}if(!UseJobFuel(digger,1))return;
            MaterialLot material;var pile=Pile(job.source);if(pile!=null)material=pile.Scoop(amount);else{var deposit=Deposit(job.source);material=deposit.remaining.Take(amount);deposit.removed+=amount;}digger.input.bulk.Add(material);job.status="Digging · loading bucket for dump trucks";
        }
        long LoadTruckFromExcavator(IndustrialMachine truck,long count){ReadMiningSites();if(!miningSites.TryGetValue(truck.haul.source,out var site)){truck.haul.waitingForExcavator=true;truck.haul.blockedTicks++;truck.haul.status="Waiting for an excavator · assign AUTO at this node";return 0;}
            foreach(var digger in site){if(digger.owner!=truck.owner||!digger.haul.active||digger.haul.phase!=1||!digger.enabled||digger.integrity<=0||digger.pose.Distance(truck.pose)>12)continue;long amount=Math.Min(count,digger.input.bulk.litres);if(amount<=0)continue;if(!UseJobFuel(digger,1)){truck.haul.waitingForExcavator=true;truck.haul.blockedTicks++;truck.haul.status="Excavator #"+digger.id+" needs fuel";return 0;}if(Inventory.TransferBulk(digger.input,truck.input,amount)){truck.haul.waitingForExcavator=false;truck.haul.blockedTicks=0;truck.haul.lastLoadTick=tick;digger.haul.status="Bucket-loading truck #"+truck.id;truck.haul.status="Being loaded by excavator #"+digger.id;return amount;}}
            truck.haul.waitingForExcavator=true;truck.haul.blockedTicks++;truck.haul.status="Waiting for excavator bucket / clear loading berth";return 0;
        }
        public string WasteSiteError(long sluiceId,FramePose pose){var sluice=Machine(sluiceId);if(sluice==null||sluice.definition!="sluice"||!Valid(pose)||pose.body!=sluice.pose.body||pose.frame!=sluice.pose.frame||sluice.pose.Distance(pose)<25||sluice.pose.Distance(pose)>100)return "Tailings dump needs clear ground 25 to 100 m from its sluice";foreach(var m in machines)if(!m.integratedLogistics&&m.pose.Distance(pose)<8+m.Definition.Radius)return "Tailings dump overlaps machinery";foreach(var pile in piles)if(pile.pose.Distance(pose)<16)return "Tailings dump overlaps a pile";foreach(var obstacle in haulObstacles)if(IndustrialHaulNavigation.BuildingContains(obstacle,pose,8))return "Tailings dump overlaps construction";if(HaulBlocked(pose,0)!=null)return "Tailings dump is obstructed";return null;}
        internal void ApplyWasteSite(IndustrialWasteSite site){var sluice=Machine(site.sluice);if(sluice==null||sluice.definition!="sluice")throw new InvalidOperationException("Missing sluice for tailings dump");if(Pile(site.pile)==null){if(nextId!=site.pile)throw new InvalidOperationException("Tailings site allocator mismatch");piles.Add(new DirtPile{id=AllocateId(),owner=sluice.owner,pose=site.pose,tailingsPile=true,tailings=new Inventory{capacity=100000}});}sluice.tailingsDump=site.pile;}
    }
}
